(433639, 39512, 9441, '<td valign="top">very grainy</td>', 'very grainy', '2003-09-29 02:24:32.000000', NULL, 1),
(433641, 39521, 10084, '<td valign="top">Such a dynamic shot. Great depth of field really makes the dog pop out of the picture. It would have been really nice to get more of the shadow to show the height of the dog jumping. Maybe a vertical crop would make the dog seem to jump higher. Dog seems a bit dark on left side. A tiny bit more light would give more details. Great picture. Would make for a good Summer postcard.</td>', 'Such a dynamic shot. Great depth of field really makes the dog pop out of the picture. It would have been really nice to get more of the shadow to show the height of the dog jumping. Maybe a vertical crop would make the dog seem to jump higher. Dog seems a bit dark on left side. A tiny bit more light would give more details. Great picture. Would make for a good Summer postcard.', '2003-09-29 02:25:08.000000', NULL, 1),
(433643, 39901, 9441, '<td valign="top">I love the reflection you captured in the bubble...that''s too cool!</td>', 'I love the reflection you captured in the bubble...that''s too cool!', '2003-09-29 02:25:48.000000', NULL, 1),
(433648, 39521, 9441, '<td valign="top">wonderful fun photo!  I love the action and expression you captured...very sharp and clear and crisp photo!  My first 10 to give any one in this challenge...congratulations!!</td>', 'wonderful fun photo!  I love the action and expression you captured...very sharp and clear and crisp photo!  My first 10 to give any one in this challenge...congratulations!!', '2003-09-29 02:29:56.000000', NULL, 1),
