(434564, 39876, 327, '<td valign="top">Pretty dark, but I see the blue is dark and you don''t have a lot of sun to work with. Nice all the same.</td>', 'Pretty dark, but I see the blue is dark and you don''t have a lot of sun to work with. Nice all the same.', '2003-09-29 18:57:10.000000', NULL, 1),
(434566, 40048, 327, '<td valign="top">Looks like an add for a travel mag. Neat light, little too bright, but still it''s good shooting.</td>', 'Looks like an add for a travel mag. Neat light, little too bright, but still it''s good shooting.', '2003-09-29 18:57:55.000000', NULL, 1),
(434569, 39995, 327, '<td valign="top">Great sky, great blue. The shot is just a bit boring. I''m impressed with your view here, and think this is right on for the challenge.</td>', 'Great sky, great blue. The shot is just a bit boring. I''m impressed with your view here, and think this is right on for the challenge.', '2003-09-29 18:58:53.000000', NULL, 1),
(434571, 39935, 327, '<td valign="top">In flight....yes you are. Pretty sky but the composition from your seat was not the best it could of been.</td>', 'In flight....yes you are. Pretty sky but the composition from your seat was not the best it could of been.', '2003-09-29 18:59:54.000000', NULL, 1),
(434572, 39991, 327, '<td valign="top">Mystery, spooks and bad weather! Lethal combo. Some grain/noise but that is over looked by me. The right sided crop is a bit too tight......however the flight of the birds is very nice.</td>', 'Mystery, spooks and bad weather! Lethal combo. Some grain/noise but that is over looked by me. The right sided crop is a bit too tight......however the flight of the birds is very nice.', '2003-09-29 19:01:52.000000', NULL, 1),
(434574, 40026, 327, '<td valign="top">I guess it''s the flash that bothers me in this shot....that and I don''t see the full bird here due to the dark background. I don''t dismiss this shot, or even dislike it. You did capture flight</td>', 'I guess it''s the flash that bothers me in this shot....that and I don''t see the full bird here due to the dark background. I don''t dismiss this shot, or even dislike it. You did capture flight', '2003-09-29 19:03:50.000000', NULL, 1),
(434575, 39192, 327, '<td valign="top">Great capture.....in the right place at the right time. I really didn''t think the crows would stand there with the eagle there.....? Humm you did well.</td>', 'Great capture.....in the right place at the right time. I really didn''t think the crows would stand there with the eagle there.....? Humm you did well.', '2003-09-29 19:04:56.000000', NULL, 1),
(434578, 39936, 327, '<td valign="top">Not too bad....they aren''t easy to photography when moving. You did well to get this.</td>', 'Not too bad....they aren''t easy to photography when moving. You did well to get this.', '2003-09-29 19:07:49.000000', NULL, 1),
(434581, 39956, 327, '<td valign="top">You caught flight, but I''m not fond of the composition and light.</td>', 'You caught flight, but I''m not fond of the composition and light.', '2003-09-29 19:09:20.000000', NULL, 1),
