(434658, 39018, 1005, '<td valign="top">Very nice shot.  Too bad the sky was so blue (it sort of kills the afterburner a bit).  9 Rob the Swash</td>', 'Very nice shot.  Too bad the sky was so blue (it sort of kills the afterburner a bit).  9 Rob the Swash', '2003-09-29 19:55:36.000000', NULL, 1),
