(438692, 39580, 12733, '<td valign="top">Interesting lighting and viewpoint. It''s a little difficult to make out what is happening, possibly because the very high key diffuses details.</td>', 'Interesting lighting and viewpoint. It''s a little difficult to make out what is happening, possibly because the very high key diffuses details.', '2003-10-03 08:56:29.000000', NULL, 1),
(438695, 39666, 12733, '<td valign="top">Beautiful closeup; might live up to its name better if the source of fuel showed more, but that''s picky.</td>', 'Beautiful closeup; might live up to its name better if the source of fuel showed more, but that''s picky.', '2003-10-03 09:01:08.000000', NULL, 1),
