(438957, 40089, 6771, '<td valign="top">I have no idea what that is, but I like the blue of the sky behind the white smoke. Good Fast shutter speed ot get that one<br/></td>', 'I have no idea what that is, but I like the blue of the sky behind the white smoke. Good Fast shutter speed ot get that one', '2003-10-03 15:40:33.000000', NULL, 1),
(438961, 39994, 6771, '<td valign="top">Good catch of a day in the life of.  The horizon line is a bit off.  I would like to see more DOF to the birds and not a landscape, since they are really the subject.  hard to do on those moving buggers</td>', 'Good catch of a day in the life of.  The horizon line is a bit off.  I would like to see more DOF to the birds and not a landscape, since they are really the subject.  hard to do on those moving buggers', '2003-10-03 15:43:06.000000', NULL, 1),
(438962, 39794, 6771, '<td valign="top">A great attempt.  You got it framed.  the problem with moving things is they like to get out of the focus range fast. Expecially an airplane.  That is what this photo suffers from.  It is soft on focus from just getting out of the DOF when locked on.  Maybe a faster shutter speed would of helped?</td>', 'A great attempt.  You got it framed.  the problem with moving things is they like to get out of the focus range fast. Expecially an airplane.  That is what this photo suffers from.  It is soft on focus from just getting out of the DOF when locked on.  Maybe a faster shutter speed would of helped?', '2003-10-03 15:45:20.000000', NULL, 1),
(438965, 39942, 6771, '<td valign="top">Very interesting angle caught here.  Love the colors off the water and their effect.  The problem I see is that it does not bring the bird out. He seems lost in the photo, without being highlighted.  It is like he blurs into the water.  If you understand that(?)</td>', 'Very interesting angle caught here.  Love the colors off the water and their effect.  The problem I see is that it does not bring the bird out. He seems lost in the photo, without being highlighted.  It is like he blurs into the water.  If you understand that(?)', '2003-10-03 15:47:43.000000', NULL, 1),
(438969, 39124, 6771, '<td valign="top">Where are you people catching all the Bald Eagles?  We usually have about 20-30 down near the river here and haven''t seen much of em.  I like the negative space on this.  I would like to see the eagle in one of the left thirds areas.  Give more of a sense of going somewhere.</td>', 'Where are you people catching all the Bald Eagles?  We usually have about 20-30 down near the river here and haven''t seen much of em.  I like the negative space on this.  I would like to see the eagle in one of the left thirds areas.  Give more of a sense of going somewhere.', '2003-10-03 15:50:52.000000', NULL, 1),
(438972, 40062, 6771, '<td valign="top">Looks way up there.  Great negative space, but would like to have seen the glider positioned in the top left, so that it looks like it is flying into the shot, and not out (?)</td>', 'Looks way up there.  Great negative space, but would like to have seen the glider positioned in the top left, so that it looks like it is flying into the shot, and not out (?)', '2003-10-03 15:53:15.000000', NULL, 1),
(438973, 39044, 6771, '<td valign="top">Very pretty shot.  Like the way the wing comes into the shot and above the horizon line.  Would have liked to see a bit more "light" on the (clouds) below to give it just a touch more texture.</td>', 'Very pretty shot.  Like the way the wing comes into the shot and above the horizon line.  Would have liked to see a bit more "light" on the (clouds) below to give it just a touch more texture.', '2003-10-03 15:54:48.000000', NULL, 1),
(438975, 39996, 6771, '<td valign="top">I use to love these things.  I actually thought of these myself, but could not find any.  Tough challenge to shoot these.  I like that they have a motion blur to them, shows they fly.  Did you try shooting from a bit farther away with a longer exposure time to get a blur down the path of their flight?  That is what I had thought of.  Probably need a lot less lighting to get that though.</td>', 'I use to love these things.  I actually thought of these myself, but could not find any.  Tough challenge to shoot these.  I like that they have a motion blur to them, shows they fly.  Did you try shooting from a bit farther away with a longer exposure time to get a blur down the path of their flight?  That is what I had thought of.  Probably need a lot less lighting to get that though.', '2003-10-03 15:57:47.000000', NULL, 1),
(438977, 39986, 6771, '<td valign="top">Excellent shot tip to tip.  I really like how this one is presented.  Good balance. the wings in the upper right and lower left thirds area, draw you into the canopy and then you notice the pilot</td>', 'Excellent shot tip to tip.  I really like how this one is presented.  Good balance. the wings in the upper right and lower left thirds area, draw you into the canopy and then you notice the pilot', '2003-10-03 15:59:42.000000', NULL, 1),
(438978, 39910, 6771, '<td valign="top">Excellent capture.  that a P51 Mustang?  Tough shot, or you have a great zoom, to get away with no camera or photographer noticeable in the shot.  Nice job on focus</td>', 'Excellent capture.  that a P51 Mustang?  Tough shot, or you have a great zoom, to get away with no camera or photographer noticeable in the shot.  Nice job on focus', '2003-10-03 16:02:19.000000', NULL, 1),
(438980, 40092, 6771, '<td valign="top">Nice time to take this shot.  Love the background. I think I would have foregone using the flash on this one.  It illuminates a few of the birds and then makes them look really blurry.  Silhouetting them would have worked better, but that is just my opinion.</td>', 'Nice time to take this shot.  Love the background. I think I would have foregone using the flash on this one.  It illuminates a few of the birds and then makes them look really blurry.  Silhouetting them would have worked better, but that is just my opinion.', '2003-10-03 16:05:09.000000', NULL, 1),
(438983, 40041, 6771, '<td valign="top">Great perspective.  Southwest airlines would love this shot.  I like the way the light plays over the fuselage and changes the color, but it is a touch too bright/neon lookking on the one side.  Great shot though</td>', 'Great perspective.  Southwest airlines would love this shot.  I like the way the light plays over the fuselage and changes the color, but it is a touch too bright/neon lookking on the one side.  Great shot though', '2003-10-03 16:07:46.000000', NULL, 1),
(438984, 39133, 6771, '<td valign="top">Nice catch.  Shutter speed 1/50000th?  (C:  Just barely a motion blur there.  Very crisp besides that.  ALmost looks like he has no wings at all, the way they blend in.  Great shot</td>', 'Nice catch.  Shutter speed 1/50000th?  (C:  Just barely a motion blur there.  Very crisp besides that.  ALmost looks like he has no wings at all, the way they blend in.  Great shot', '2003-10-03 16:09:21.000000', NULL, 1),
(438987, 40071, 6771, '<td valign="top">Keep your mouth closed!  This is a tough shot, and good try.  It is overexposed, a faster shutter speed may have corrected alot of the problems with this shot.  would have stopped the motion more (blurry) and darkened up the sky, and fixed the overexposure some.  Keep at it.  Only learn from trying and trying again.</td>', 'Keep your mouth closed!  This is a tough shot, and good try.  It is overexposed, a faster shutter speed may have corrected alot of the problems with this shot.  would have stopped the motion more (blurry) and darkened up the sky, and fixed the overexposure some.  Keep at it.  Only learn from trying and trying again.', '2003-10-03 16:12:49.000000', NULL, 1),
(438990, 39964, 6771, '<td valign="top">Hahahaha.  Very cool.  I thought this was a skydiver when I saw the thumbnail.  Nice catch.  Looks like arms outstretched to the wind.  Nice negative space.  Looks like it is at 20,000 feet.  Good work!</td>', 'Hahahaha.  Very cool.  I thought this was a skydiver when I saw the thumbnail.  Nice catch.  Looks like arms outstretched to the wind.  Nice negative space.  Looks like it is at 20,000 feet.  Good work!', '2003-10-03 16:14:47.000000', NULL, 1),
(439026, 39517, 3599, '<td valign="top">I like how you showed the airplane in relation to the ground.  Not that you have anything to do with it but that is one ugly paint job!  At least it gets your attention though.  Nice work.</td>', 'I like how you showed the airplane in relation to the ground.  Not that you have anything to do with it but that is one ugly paint job!  At least it gets your attention though.  Nice work.', '2003-10-03 18:07:54.000000', NULL, 1),
(439028, 40085, 12786, '<td valign="top">I really like this photo!! well done!</td>', 'I really like this photo!! well done!', '2003-10-03 18:20:28.000000', NULL, 1),
(439033, 39886, 12076, '<td valign="top">Best shot of the bunch.  Great highlighting on the wings.  -10-</td>', 'Best shot of the bunch.  Great highlighting on the wings.  -10-', '2003-10-03 18:37:33.000000', NULL, 1),
(439034, 39898, 12076, '<td valign="top">Should be a ribbon winner.  Great interpretation.  May lack just a bit of sharpness.  -10-</td>', 'Should be a ribbon winner.  Great interpretation.  May lack just a bit of sharpness.  -10-', '2003-10-03 18:38:55.000000', NULL, 1),
(439035, 39870, 12076, '<td valign="top">I really like this.  Would be neat if you could get the one seed just removed from the plant. (Just after lift-off.)  Would be difficult...   -8-</td>', 'I really like this.  Would be neat if you could get the one seed just removed from the plant. (Just after lift-off.)  Would be difficult...   -8-', '2003-10-03 18:40:39.000000', NULL, 1),
(439037, 40089, 9462, '<td valign="top">What is that a hotair ballon?</td>', 'What is that a hotair ballon?', '2003-10-03 19:00:15.000000', NULL, 1),
(439056, 39873, 10084, '<td valign="top">Beautiful focus. Great details on the strands of the feathers. Great blue hue in the feather. Background helps to bring out the feather and make it pop out of the picture.</td>', 'Beautiful focus. Great details on the strands of the feathers. Great blue hue in the feather. Background helps to bring out the feather and make it pop out of the picture.', '2003-10-03 19:51:22.000000', NULL, 1),
(439077, 39867, 8367, '<td valign="top">Very nice capture. This would look beautiful without the brown border. Maybe just white or a pale neutral shade would enhance it better... IMO...</td>', 'Very nice capture. This would look beautiful without the brown border. Maybe just white or a pale neutral shade would enhance it better... IMO...', '2003-10-03 20:08:18.000000', NULL, 1),
(439200, 39893, 8911, '<td valign="top">I have to wonder what happened when it hit all the pricklies.... :) For all that the bubble is theoretically the subject, however, the focus is distinctly on the sharp points in the background. Not sure if that was deliberate or not; if so, it doesn''t quite work for me in this context. The capture of the colors on the bubble''s surface is really nice.</td>', 'I have to wonder what happened when it hit all the pricklies.... :) For all that the bubble is theoretically the subject, however, the focus is distinctly on the sharp points in the background. Not sure if that was deliberate or not; if so, it doesn''t quite work for me in this context. The capture of the colors on the bubble''s surface is really nice.', '2003-10-03 23:57:49.000000', NULL, 1),
(439209, 40042, 8911, '<td valign="top">I don''t know about the title, but the photo''s nice and crisp and flying...er, floating.... That string sure makes it look like there''s no escaping here, though, it''s awfully taut.</td>', 'I don''t know about the title, but the photo''s nice and crisp and flying...er, floating.... That string sure makes it look like there''s no escaping here, though, it''s awfully taut.', '2003-10-04 00:11:39.000000', NULL, 1),
(439218, 39543, 8911, '<td valign="top">The picture is just a little fuzzy in terms of focus - I''d have liked it either softer or crisper. The buildings capture and hold my attention more, given the variety of shapes and tones there, than the sky does.</td>', 'The picture is just a little fuzzy in terms of focus - I''d have liked it either softer or crisper. The buildings capture and hold my attention more, given the variety of shapes and tones there, than the sky does.', '2003-10-04 00:33:08.000000', NULL, 1),
(439220, 39876, 8637, '<td valign="top">Nice photo...great backdrop...would have been nice to have more illumination on the balloon.</td>', 'Nice photo...great backdrop...would have been nice to have more illumination on the balloon.', '2003-10-04 00:37:01.000000', NULL, 1),
(439222, 39959, 8637, '<td valign="top">Neat shot...wing clipped a little</td>', 'Neat shot...wing clipped a little', '2003-10-04 00:37:22.000000', NULL, 1),
(439223, 40026, 8637, '<td valign="top">Nice capture...excellent illumination!</td>', 'Nice capture...excellent illumination!', '2003-10-04 00:38:04.000000', NULL, 1),
(439225, 39996, 8637, '<td valign="top">I tried this same shot...very difficult and finally gave up and did not enter...you did nice job with the helicopter idea.</td>', 'I tried this same shot...very difficult and finally gave up and did not enter...you did nice job with the helicopter idea.', '2003-10-04 00:38:47.000000', NULL, 1),
(439226, 39511, 8637, '<td valign="top">Nice idea but lighting not too good...flash might have helped?  Also clipped wing tip.</td>', 'Nice idea but lighting not too good...flash might have helped?  Also clipped wing tip.', '2003-10-04 00:39:43.000000', NULL, 1),
(439227, 40081, 8637, '<td valign="top">Oh yeah!!</td>', 'Oh yeah!!', '2003-10-04 00:40:05.000000', NULL, 1),
(439228, 39542, 12452, '<td valign="top">looks very dangerous - but amazing no less<br/></td>', 'looks very dangerous - but amazing no less', '2003-10-04 00:42:03.000000', NULL, 1),
(439229, 39849, 8637, '<td valign="top">neat shot!</td>', 'neat shot!', '2003-10-04 00:43:19.000000', NULL, 1),
(439230, 39812, 8637, '<td valign="top">Light seems a bit harsh...neat angle though.</td>', 'Light seems a bit harsh...neat angle though.', '2003-10-04 00:43:49.000000', NULL, 1),
(439231, 39563, 8637, '<td valign="top">Head seems a bit out of focus but super catch.</td>', 'Head seems a bit out of focus but super catch.', '2003-10-04 00:44:25.000000', NULL, 1),
(439233, 39928, 8637, '<td valign="top">Chutist is a bit out of focus.</td>', 'Chutist is a bit out of focus.', '2003-10-04 00:44:48.000000', NULL, 1),
(439234, 39942, 8637, '<td valign="top">Super sharp...very nice.</td>', 'Super sharp...very nice.', '2003-10-04 00:45:13.000000', NULL, 1),
(439235, 39580, 8637, '<td valign="top">Very neat...</td>', 'Very neat...', '2003-10-04 00:45:38.000000', NULL, 1),
(439236, 39133, 8637, '<td valign="top">Wow!  Simply WOW.</td>', 'Wow!  Simply WOW.', '2003-10-04 00:46:01.000000', NULL, 1),
(439238, 39986, 8637, '<td valign="top">I think the border distracts...but neat capture.</td>', 'I think the border distracts...but neat capture.', '2003-10-04 00:46:55.000000', NULL, 1),
(439239, 39603, 8637, '<td valign="top">Critter moved a bit on you...little blurred.</td>', 'Critter moved a bit on you...little blurred.', '2003-10-04 00:47:14.000000', NULL, 1),
(439241, 39893, 8637, '<td valign="top">Beautiful...well done and neat composition.</td>', 'Beautiful...well done and neat composition.', '2003-10-04 00:51:37.000000', NULL, 1),
(439242, 39870, 8637, '<td valign="top">Very nice...had planned a similar shot and the rains came down and nocked all the seed off!  Very well done.</td>', 'Very nice...had planned a similar shot and the rains came down and nocked all the seed off!  Very well done.', '2003-10-04 00:52:12.000000', NULL, 1),
(439248, 40071, 1686, '<td valign="top">interesting , too much digital noise</td>', 'interesting , too much digital noise', '2003-10-04 01:21:22.000000', NULL, 1),
(439249, 40069, 8911, '<td valign="top">Nice crisp shot as far as the moth not moving, but I think the lighting did it a real disservice, the glare blowing out the details on the moth almost completely, and even somewhat on the flowers. I would have liked a bit more depth of focus, so that the back of the moth\\''s wings were not so blurry (and the right two flowers, as well).</td>', 'Nice crisp shot as far as the moth not moving, but I think the lighting did it a real disservice, the glare blowing out the details on the moth almost completely, and even somewhat on the flowers. I would have liked a bit more depth of focus, so that the back of the moth\\''s wings were not so blurry (and the right two flowers, as well).', '2003-10-04 01:21:23.000000', NULL, 1),
(439250, 39983, 8911, '<td valign="top">Wow - quite a moment to capture. It''s a pity the light is so bright, though - it washes out the edges of the bird.</td>', 'Wow - quite a moment to capture. It''s a pity the light is so bright, though - it washes out the edges of the bird.', '2003-10-04 01:22:00.000000', NULL, 1),
(439251, 39851, 8911, '<td valign="top">Nice, crisp shot - the frisbee being a bit high and blurred, it seems almost less the subject than the trees or pole that are so crisp and take up so much of the frame. I wonder if timing the shot differently, when it was lower, or changing the angle to look more up at it, might have made the frisbee more prominent in the picture.</td>', 'Nice, crisp shot - the frisbee being a bit high and blurred, it seems almost less the subject than the trees or pole that are so crisp and take up so much of the frame. I wonder if timing the shot differently, when it was lower, or changing the angle to look more up at it, might have made the frisbee more prominent in the picture.', '2003-10-04 01:24:44.000000', NULL, 1),
(439252, 40095, 1686, '<td valign="top">nice trail, late shutter curtain?</td>', 'nice trail, late shutter curtain?', '2003-10-04 01:28:21.000000', NULL, 1),
(439263, 39818, 8911, '<td valign="top">Nice colors/composition - focus is on the foreground flowers, though, and the bee is out of focus - whereas I''d assume it was the intended subject of a flight photo.</td>', 'Nice colors/composition - focus is on the foreground flowers, though, and the bee is out of focus - whereas I''d assume it was the intended subject of a flight photo.', '2003-10-04 02:24:30.000000', NULL, 1),
(439264, 39959, 10084, '<td valign="top">Great contrast helps to bring out the beautiful feathers in the bird. Love the slight blur in the wings helps to show motion and the sense of flight. The depth of field helps bring out the bird from the sky in the backgorund. Great fluffy clouds too.</td>', 'Great contrast helps to bring out the beautiful feathers in the bird. Love the slight blur in the wings helps to show motion and the sense of flight. The depth of field helps bring out the bird from the sky in the backgorund. Great fluffy clouds too.', '2003-10-04 02:26:47.000000', NULL, 1),
(439266, 39640, 10084, '<td valign="top">Beautiful blue hue in the sky really adds interest to the picture. Contrast in the birds against the sky really help bring them out of the shot. A lot of people might complain about the landscape but I like it. It gives scale to the image and give the picture an immense or larger then life feeling. Great shot. Excellent frame choice.</td>', 'Beautiful blue hue in the sky really adds interest to the picture. Contrast in the birds against the sky really help bring them out of the shot. A lot of people might complain about the landscape but I like it. It gives scale to the image and give the picture an immense or larger then life feeling. Great shot. Excellent frame choice.', '2003-10-04 02:30:32.000000', NULL, 1),
(439267, 39140, 10084, '<td valign="top">Really great composition. The angle you chose sends out a feeling of flight. The blue in the sky frames the plane very well and makes it pop out of the image. Great colors in the plane itself.<br/> <br/>Would make for a gread ad for the airline or a postcard that the airline would hand out to the passengers. Very impressive shot.</td>', 'Really great composition. The angle you chose sends out a feeling of flight. The blue in the sky frames the plane very well and makes it pop out of the image. Great colors in the plane itself. Would make for a gread ad for the airline or a postcard that the airline would hand out to the passengers. Very impressive shot.', '2003-10-04 02:32:57.000000', NULL, 1),
(439268, 39133, 2717, '<td valign="top">The Winner!! 10</td>', 'The Winner!! 10', '2003-10-04 02:34:39.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(439269, 39554, 10084, '<td valign="top">Very cool concept. I feel that the tableleg is a bit distracting. Great contrast in the shot. Love the fine details in the wastebasket. Can''t wait to hear about your settings and way you capture the shot.</td>', 'Very cool concept. I feel that the tableleg is a bit distracting. Great contrast in the shot. Love the fine details in the wastebasket. Can''t wait to hear about your settings and way you capture the shot.', '2003-10-04 02:36:39.000000', NULL, 1),
(439281, 40081, 12796, '<td valign="top">Wow.. This is an amazing shot.! I will give a 10 to this.</td>', 'Wow.. This is an amazing shot.! I will give a 10 to this.', '2003-10-04 03:27:56.000000', NULL, 1),
(439296, 40085, 11241, '<td valign="top">I love this photo, very simple....But it could be a little sharper...I would give it a 9</td>', 'I love this photo, very simple....But it could be a little sharper...I would give it a 9', '2003-10-04 05:25:03.000000', NULL, 1),
