(439981, 39893, 1031, '<td valign="top">Won''t last long among those spiky plants!</td>', 'Won''t last long among those spiky plants!', '2003-10-06 00:06:24.000000', NULL, 1),
(439982, 40071, 8911, '<td valign="top">An impressive number of birds, but very out-of-focus and grainy...I don''t know if you were trying for that effect, but I find it very distracting, making this really more a picture of bird shapes than birds.</td>', 'An impressive number of birds, but very out-of-focus and grainy...I don''t know if you were trying for that effect, but I find it very distracting, making this really more a picture of bird shapes than birds.', '2003-10-06 00:07:54.000000', NULL, 1),
(439987, 39996, 8911, '<td valign="top">Augh - I''m having flashbacks to cleaning my deck, here.... Them otion blur is a nice effect, but I think I''d like it better if the shutter had been a little quicker - the blur here is enough that (at least for me) it makes looking at them hard on the eyes. I like the decision to shoot them against just the cloudy sky - the color contrast is particularly striking.</td>', 'Augh - I''m having flashbacks to cleaning my deck, here.... Them otion blur is a nice effect, but I think I''d like it better if the shutter had been a little quicker - the blur here is enough that (at least for me) it makes looking at them hard on the eyes. I like the decision to shoot them against just the cloudy sky - the color contrast is particularly striking.', '2003-10-06 00:10:57.000000', NULL, 1),
