(440004, 40032, 5705, '<td valign="top">NIce close up -- 7</td>', 'NIce close up -- 7', '2003-10-06 00:18:28.000000', NULL, 1),
(440005, 39984, 8911, '<td valign="top">I love the title - these two are so funny-looking as they come in to land, the humor suits them perfectly. I really like the capture; the water seems to have some noise, but the birds don\''t (that I can see); not sure why.</td>', 'I love the title - these two are so funny-looking as they come in to land, the humor suits them perfectly. I really like the capture; the water seems to have some noise, but the birds don\''t (that I can see); not sure why.', '2003-10-06 00:18:29.000000', NULL, 1),
(440006, 39554, 5705, '<td valign="top">Original Shot--  must have been done with some sort of strobe-- 8</td>', 'Original Shot--  must have been done with some sort of strobe-- 8', '2003-10-06 00:19:25.000000', NULL, 1),
(440007, 39891, 8911, '<td valign="top">Proof that flight doesn''t always have to be completely graceful.... I like the fact that the birds are fairly crisp, and the background''s not; the tree would be a distraction if it were in sharp focus.</td>', 'Proof that flight doesn''t always have to be completely graceful.... I like the fact that the birds are fairly crisp, and the background''s not; the tree would be a distraction if it were in sharp focus.', '2003-10-06 00:19:42.000000', NULL, 1),
