(440026, 39968, 5705, '<td valign="top">Damn, then came the Dream Challenge Next!!</td>', 'Damn, then came the Dream Challenge Next!!', '2003-10-06 00:39:29.000000', NULL, 1),
(440027, 39802, 5705, '<td valign="top">Just stopped and had to stare!  this IMO is the BEST photo in the challenge--<br/>Its very emotive, and captures the Spirit of a young mind--<br/> <br/>The framing, tones, and subject are all flawless-- I hope this gets offered as a print, its been awhile since Ive seen this high quality on DPC, its just great, and gonna be in my Favorites list--  10+++++++++++++++++++++++++++</td>', 'Just stopped and had to stare!  this IMO is the BEST photo in the challenge--Its very emotive, and captures the Spirit of a young mind-- The framing, tones, and subject are all flawless-- I hope this gets offered as a print, its been awhile since Ive seen this high quality on DPC, its just great, and gonna be in my Favorites list--  10+++++++++++++++++++++++++++', '2003-10-06 00:42:51.000000', NULL, 1),
